/* Declarative problem catalog. Each problem owns files, conversations and submissions. */
const makeBaseline=(kind,target,features)=>{
  if(kind==='text')return `# THPT Chuyên Trần Đại Nghĩa · Baseline\nimport pandas as pd\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.feature_extraction.text import TfidfVectorizer\nfrom sklearn.linear_model import LogisticRegression\n\ntrain = pd.read_csv("data/train.csv")\ntest = pd.read_csv("data/test.csv")\nmodel = make_pipeline(\n    TfidfVectorizer(ngram_range=(1, 2)),\n    LogisticRegression(max_iter=1000)\n)\nmodel.fit(train["text"], train["${target}"])\npd.DataFrame({"id": test["id"],\n              "${target}": model.predict(test["text"])}\n).to_csv("submission.csv", index=False)\n\n# Đánh giá trên validation trước khi dự đoán test.\n# Dữ liệu mẫu chưa đại diện cho dữ liệu thực tế.\n`;
  return `# THPT Chuyên Trần Đại Nghĩa · Baseline\nimport pandas as pd\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.${kind==='regression'?'linear_model import Ridge':'linear_model import LogisticRegression'}\n\ntrain = pd.read_csv("data/train.csv")\ntest = pd.read_csv("data/test.csv")\nfeatures = ${JSON.stringify(features)}\nmodel = make_pipeline(\n    StandardScaler(),\n    ${kind==='regression'?'Ridge(alpha=1.0)':'LogisticRegression(max_iter=1000)'}\n)\nmodel.fit(train[features], train["${target}"])\npredictions = model.predict(test[features])\npd.DataFrame({"id": test["id"],\n              "${target}": predictions}\n).to_csv("submission.csv", index=False)\n\n# Tách validation phù hợp trước khi đánh giá.\n# Với chuỗi thời gian, chia theo thời gian, không shuffle.\n`;
};
function problem(spec){return {...spec,files:{'baseline.py':makeBaseline(spec.kind,spec.target,spec.features),'data/train.csv':spec.train,'data/test.csv':spec.test,'submission.csv':spec.sample,'requirements.txt':'pandas>=2.0\nscikit-learn>=1.3\n','README.md':`# ${spec.title}\n\n${spec.summary}\n\nMetric: ${spec.metric}\nBài nộp: id,${spec.target}\n\nDữ liệu trong bài là mẫu minh họa.\nChạy: pip install -r requirements.txt\nSau đó: python baseline.py\n`}};}
